import{_ as o,a0 as p,w as s,s as n,ao as d,I as i,x as l,a1 as r,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Mydumper - MySQL資料庫備份工具 | LCTT x X-CMD","titleTemplate":false,"description":"Mydumper - MySQL資料庫備份工具 | LCTT (201504) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Mydumper - MySQL資料庫備份工具 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Mydumper - MySQL資料庫備份工具 | LCTT (201504) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201504/20150326 Mydumper--Mysql Database Backup tool","title":"Mydumper - MySQL資料庫備份工具","tag":"201504","desc":""},"relativePath":"201504/20150326 Mydumper--Mysql Database Backup tool.md","filePath":"[post].md"}'),u={name:"201504/20150326 Mydumper--Mysql Database Backup tool.md"};function m(y,e,b,M,h,f){const t=p("Link");return s(),n("div",null,[e[13]||(e[13]=d(`<h1 id="mydumper-mysql資料庫備份工具" tabindex="-1">Mydumper - MySQL資料庫備份工具 <a class="header-anchor" href="#mydumper-mysql資料庫備份工具" aria-label="Permalink to “Mydumper - MySQL資料庫備份工具”">​</a></h1><p>Mydumper 是 MySQL 資料庫服務器備份工具，它比 MySQL 自帶的 mysqldump 快很多。它還有在轉儲的同時獲取遠程服務器二進制日誌文件的能力。</p><h3 id="mydumper-的優勢" tabindex="-1">Mydumper 的優勢 <a class="header-anchor" href="#mydumper-的優勢" aria-label="Permalink to “Mydumper 的優勢”">​</a></h3><ul><li>並行能力 (因此有高速度) 和性能 (高效的代碼避免了耗費 CPU 處理能力的字符集轉換過程)</li><li>更容易管理輸出 (每個表都對應獨立的文件，轉儲元數據等，便於查看/解析數據)</li><li>一致性 ：跨線程維護快照, 提供精確的主從日誌定位等。</li><li>可管理性 ： 支持用 PCRE 來包含/排除指定的資料庫和表(LCTT譯註：PCRE，Perl Compatible Regular Expression，Perl兼容正則表達式)</li></ul><h3 id="在ubuntu上安裝-mydumper" tabindex="-1">在Ubuntu上安裝 mydumper <a class="header-anchor" href="#在ubuntu上安裝-mydumper" aria-label="Permalink to “在Ubuntu上安裝 mydumper”">​</a></h3><p>打開終端運行以下命令</p><pre><code>sudo apt-get install mydumper
</code></pre><h3 id="使用-mydumper" tabindex="-1">使用 Mydumper <a class="header-anchor" href="#使用-mydumper" aria-label="Permalink to “使用 Mydumper”">​</a></h3><h4 id="語法" tabindex="-1">語法 <a class="header-anchor" href="#語法" aria-label="Permalink to “語法”">​</a></h4><pre><code>mydumper [options]
</code></pre><p>應用程序選項:</p><ul><li>-B, --database 要轉儲的資料庫</li><li>-T, --tables-list 逗號分隔的轉儲表列表(不會被正則表達式排除)</li><li>-o, --outputdir 保存輸出文件的目錄</li><li>-s, --statement-size 插入語句的字節大小, 默認是1000000個字節</li><li>-r, --rows 把表按行數切塊</li><li>-c, --compress 壓縮輸出文件</li><li>-e, --build-empty-files 空表也輸出文件</li><li>-x, --regex 匹配‘db.table’的正則表達式</li><li>-i, --ignore-engines 以逗號分隔的被忽略的存儲引擎列表</li><li>-m, --no-schemas 不轉儲表架構</li><li>-k, --no-locks 不執行臨時共享讀鎖。警告: 這會導致備份的不一致性</li><li>-l, --long-query-guard 設置長查詢的計時器秒數，默認是60秒</li><li>--kill-long-queries 殺死長查詢 (而不是退出程序)</li><li>-b, --binlogs 獲取二進制日誌文件快照並轉儲數據</li><li>-D, --daemon 開啓守護進程模式</li><li>-I, --snapshot-interval 每個轉儲快照之間的間隔時間(分鐘), 需要開啓 --daemon, 默認是60分鐘</li><li>-L, --logfile 日誌文件的名字，默認是stdout</li><li>-h, --host 要連接的主機</li><li>-u, --user 有轉儲權限的用户名</li><li>-p, --password 用户密碼</li><li>-P, --port 連接的TCP/IP端口</li><li>-S, --socket 用於連接的Unix套接字文件</li><li>-t, --threads 使用的線程數，默認是4</li><li>-C, --compress-protocol 在MySQL連接上使用壓縮</li><li>-V, --version 查看程序版本號</li><li>-v, --verbose 輸出信息的等級, 0 = silent, 1 = errors, 2 = warnings, 3 = info, 默認是2</li></ul><h4 id="mydumper-例子" tabindex="-1">Mydumper 例子 <a class="header-anchor" href="#mydumper-例子" aria-label="Permalink to “Mydumper 例子”">​</a></h4><pre><code>mydumper \\
--database=$DB_NAME \\
--host=$DB_HOST \\
--user=$DB_USER \\
--password=$DB_PASS \\
--outputdir=$DB_DUMP \\
--rows=500000 \\
--compress \\
--build-empty-files \\
--threads=2 \\
--compress-protocol
</code></pre><p>Mydumper 輸出數據的説明</p><p>Mydumper 不直接指定輸出的文件，而是輸出到文件夾的文件中。--outputdir 選項指定要使用的目錄名稱。</p><p>輸出分為兩部分</p><p><strong>表結構</strong></p><p>對資料庫中的每個表，創建一個包含 CREATE TABLE 語句的文件。文件命名為：</p><p>dbname.tablename-schema.sql.gz</p><p><strong>數據</strong></p><p>每個表名跟着按 --rows 參數所切塊的數量, 創建文件名字為:</p><p>dbname.tablename.0000n.sql.gz</p><p>&quot;n&quot;從0開始.</p><p>你可以使用Myloader恢復這些備份</p><pre><code>myloader \\
--database=$DB_NAME \\
--directory=$DB_DUMP \\
--queries-per-transaction=50000 \\
--threads=10 \\
--compress-protocol \\
--verbose=3
</code></pre><hr>`,27)),i("p",null,[e[1]||(e[1]=l("via: ",-1)),r(t,{href:"http://www.ubuntugeek.com/mydumper-mysql-database-backup-tool.html"},{default:a(()=>[...e[0]||(e[0]=[l("http://www.ubuntugeek.com/mydumper-mysql-database-backup-tool.html",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=l("作者：",-1)),r(t,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:a(()=>[...e[2]||(e[2]=[l("ruchi",-1)])]),_:1}),e[6]||(e[6]=l(" 譯者：",-1)),r(t,{href:"https://github.com/ictlyh"},{default:a(()=>[...e[3]||(e[3]=[l("ictlyh",-1)])]),_:1}),e[7]||(e[7]=l(" 校對：",-1)),r(t,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[l("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=l("本文由 ",-1)),r(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[l("LCTT",-1)])]),_:1}),e[11]||(e[11]=l(" 原創翻譯，",-1)),r(t,{href:"http://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[l("Linux中國",-1)])]),_:1}),e[12]||(e[12]=l(" 榮譽推出",-1))])])}const C=o(u,[["render",m]]);export{x as __pageData,C as default};
